def fid(d, i): return f"F-{d}-{i:03d}"
def oid(f, j): return f"{f}-OPP-{j:02d}"

PRIO = ["P0-Critical","P1-High","P2-Medium","P3-Low"]
COMP = ["S","M","L","XL"]

def det_pick(key, arr):
    h = int(hashlib.sha256(key.encode()).hexdigest(), 16)
    return arr[h % len(arr)]

def effort(comp):
    return {"S":"3-5 d","M":"1-2 w","L":"3-5 w","XL":"6-10 w"}[comp]

total_features = sum(len(f) for _,_,f in DOMAINS)
assert total_features == 1000, total_features
for _,_,f in DOMAINS:
    assert len(f) == 40, len(f)

# ---- write feature catalog domain files + expansions + json/csv ----
