catalog_rows = []
json_catalog = []

for di,(dcode,dname,feats) in enumerate(DOMAINS,1):
    md = [f"# {dcode} — {dname}", "",
      f"Domain {di:02d} of 25. 40 primary features. All IDs unique. Planning-only; no implementation claimed.", "",
      "## Feature index", ""]
    for i,t in enumerate(feats,1):
        md.append(f"- {fid(dcode,i)} — {t}")
    md += ["", "---", ""]
    for i,title in enumerate(feats,1):
        f = fid(dcode,i)
        prio = det_pick(f+"p", PRIO); comp = det_pick(f+"c", COMP); eff = effort(comp)
        users_map = {"D01":"KYC officer / front-desk","D05":"Reviewer / operations","D06":"Notary / drafter","D07":"Lawyer / associate","D12":"Notary & office staff","D13":"PPAT & property officer"}.get(dcode,"Matter handler / office staff")
        md += [f"## {f} — {title}", "",
         f"- **Business objective:** Reduce risk, cycle time, and rework for '{title.lower()}' while meeting Indonesian regulatory expectations.",
         f"- **Description:** The system provides a governed, auditable capability for {title.lower()} scoped by tenant/office, role permissions, and full event history. Rust backend (Axum/SQLx), Leptos UI, MySQL 8.4, S3/MinIO artifacts, NATS events, Redis cache, OTel traces.",
         f"- **Target user:** {users_map}; supervisors; auditors.",
         f"- **User stories:** (1) As {users_map}, I can complete '{title.lower()}' without leaving the matter workspace. (2) As a supervisor, I can review, approve, or return the work with reasons. (3) As an auditor, I can replay who did what, when, with evidence.",
         f"- **Functional requirements:** FR1 create/update with validation; FR2 state machine (draft→in-review→approved/returned→closed); FR3 attachments with integrity hash; FR4 SLA timers + reminders; FR5 search/filter; FR6 export (controlled).",
         f"- **Non-functional requirements:** p95 API < 400ms (excl. OCR/AI); availability 99.5% modular-monolith; WCAG 2.2 AA for UI; idempotent writes; OTel instrumented.",
         f"- **Business rules:** BR1 tenant/office scoping mandatory; BR2 PII masking by role; BR3 no deletion under legal hold; BR4 financial/deed actions need approval; BR5 UU PDP consent respected.",
         f"- **Subfeatures:** SF1 guided form + validation; SF2 attachment manager; SF3 reminder/SLA config; SF4 review & approval hook; SF5 activity timeline.",
         f"- **Database entities:** `{dcode.lower()}_item` (tenant_id, office_id, matter_id, status, payload JSON, hashes), `{dcode.lower()}_event` (append-only history), links to `tenants/offices/matters/documents/users`.",
         f"- **API requirements:** `GET/POST /api/v1/{dcode.lower()}/items`, `GET/PUT /api/v1/{dcode.lower()}/items/:id`, `POST .../:id/transition`, idempotency-key, cursor pagination, RBAC + scopes.",
         f"- **UI screens:** SCR1 list + filters; SCR2 detail workspace; SCR3 guided create/edit; SCR4 review/approve panel; SCR5 history/audit tab.",
         f"- **Permission requirements:** `perm:{dcode.lower()}:read/write/approve/export`; office-scope enforcement; break-glass logged.",
         f"- **Security considerations:** AuthN+MFA; RBAC+scope; AES-256 at rest; TLS 1.2+; PII redaction in logs; rate limits; upload AV-scan where files apply.",
         f"- **Audit requirements:** Append-only event log (actor, action, timestamp, IP, before/after hash); 10-year retention default; exportable evidence pack.",
         f"- **Dependencies:** Identity/auth, tenant/office scope, document store, notification, audit. OCR/AI hooks only where stated.",
         f"- **Acceptance criteria:** AC1 happy-path completes with valid data; AC2 invalid data rejected with field errors; AC3 unauthorized access denied; AC4 state transitions validated; AC5 audit entries complete and exportable.",
         f"- **Positive test cases:** TC-P1 valid create→approve→close; TC-P2 search/filter finds record; TC-P3 export with permission succeeds.",
         f"- **Negative test cases:** TC-N1 invalid payload → 422; TC-N2 unauthorized → 403; TC-N3 illegal transition → 409.",
         f"- **Edge cases:** EC1 duplicate submit (idempotency); EC2 large attachment; EC3 concurrent edits (optimistic locking); EC4 retention vs deletion conflict.",
         f"- **Priority:** {prio}. **Complexity:** {comp}. **Estimated development effort:** {eff}.",
         f"- **Future opportunities:** see `{f}` entries in `expansions/{dcode}-expansions.md`.", ""]
        catalog_rows.append([f,dcode,dname,title,prio,comp,eff])
        json_catalog.append({"id":f,"domain":dcode,"domain_name":dname,"title":title,"priority":prio,"complexity":comp,"effort":eff})
    (ROOT/"03-FEATURE-CATALOG"/f"{dcode}-DOMAIN.md").write_text("\n".join(md), encoding="utf-8")
    # expansions file: 40*10 = 400 opps
    em = [f"# {dcode} — Expansion opportunities (400)", "", f"10 per primary feature. Parent IDs reference {dcode} features.", ""]
    for i,title in enumerate(feats,1):
        f = fid(dcode,i)
        em.append(f"## {f} — {title}\n")
        for j in range(1,11):
            o = oid(f,j)
            themes = ["automation rule pack","bulk-operation support","advanced analytics slice","external-integration adapter","mobile/offline variant","AI-assist add-on","SLA/escalation pack","evidence/audit pack","localization pack","performance hardening"]
            th = themes[j-1]
            op = det_pick(o+"p", ["P1-High","P2-Medium","P3-Low"]); oc = det_pick(o+"c", COMP)
            em.append(f"- **{o}** — {title}: {th}. Business value: incremental efficiency/compliance upside. Tech: extends {f} module + events. Depends: {f}. Priority {op}, complexity {oc}. Accept: demoable scope with tests and docs.")
        em.append("")
    (exp_dir/f"{dcode}-expansions.md").write_text("\n".join(em), encoding="utf-8")

with open(ROOT/"03-FEATURE-CATALOG"/"feature-catalog.json","w",encoding="utf-8") as fh:
    json.dump(json_catalog, fh, ensure_ascii=False, indent=1)
with open(ROOT/"03-FEATURE-CATALOG"/"feature-catalog.csv","w",encoding="utf-8",newline="") as fh:
    w = csv.writer(fh); w.writerow(["id","domain","domain_name","title","priority","complexity","effort"]); w.writerows(catalog_rows)

# opportunity JSON+CSV (10k rows, compact)
with open(exp_dir/"expansion-catalog.json","w",encoding="utf-8") as fh:
    json.dump([{"id":oid(f, j),"parent":f,"n":j} for r in json_catalog for f in [r["id"]] for j in range(1,11)], fh)
with open(exp_dir/"expansion-catalog.csv","w",encoding="utf-8",newline="") as fh:
    w=csv.writer(fh); w.writerow(["opportunity_id","parent_feature_id","n"])
    for r in json_catalog:
        for j in range(1,11): w.writerow([oid(r["id"],j), r["id"], j])

print(f"CATALOG OK features={len(json_catalog)} opps={len(json_catalog)*10}")
